sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_dir;
uniform float amzp_splats;
uniform float amzp_cx;
uniform float amzp_cy;
uniform float amzp_spread;
uniform float amzp_stagger;
uniform float amzp_rough;
uniform float amzp_detail;
uniform float amzp_tendrils;
uniform float amzp_drops;
uniform float amzp_dropSize;
uniform float amzp_feather;
uniform float amzp_rimW;
layout(color) uniform half4 amzp_rimColor;
uniform float amzp_rimOp;
uniform float amzp_seed;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 advF(float2 uv, float2 pv) { float2 W = layer; float2 q = advRot((uv - pv) * W, radians(amzp_advAngle)) / max(amzp_advScale, 0.01); return q / W + pv; }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 7.137) * 43758.5453); }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float vnoise(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hh(i), hh(i + float2(1.0, 0.0)), f.x), mix(hh(i + float2(0.0, 1.0)), hh(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p) { return vnoise(p) * 0.55 + vnoise(p * 2.07 + 5.3) * 0.28 + vnoise(p * 4.13 + 1.7) * 0.17; }
    void amzRender() {
        float2 W = layer;
        float M = min(W.x, W.y);
        float2 asp = W / M;
        float2 uv = amzLayerNorm();
        float4 src = amzTexture(0, l2s(uv));
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if (C <= 0.0) { amzOutput = int(amzp_dir) == 1 ? src : float4(0.0); return; }
        if (C >= 1.0) { amzOutput = int(amzp_dir) == 1 ? float4(0.0) : src; return; }
        float2 q = (advF(uv, float2(0.5)) - 0.5) * asp;
        float2 cen = (float2(amzp_cx, 1.0 - amzp_cy) - 0.5) * asp;
        float fe = max(amzp_feather, 0.0) / M + 0.0008;
        float rw = max(amzp_rimW, 0.0) / M;
        float f = -10.0;
        float dropM = 0.0;
        float2 cell = q * 26.0 / max(amzp_dropSize, 0.1);
        float2 ci = floor(cell);
        float2 dc = (ci + 0.2 + 0.6 * float2(hh(ci + 3.1), hh(ci + 7.7))) / (26.0 / max(amzp_dropSize, 0.1));
        float dr = (0.05 + 0.13 * hh(ci + 1.3)) / 26.0 * max(amzp_dropSize, 0.1);
        bool dropOn = hh(ci + 9.4) < amzp_drops * 0.55;
        for (int i = 0; i < 10; i++) {
            if (float(i) >= amzp_splats) break;
            float fi = float(i);
            float2 c = cen + (i == 0 ? float2(0.0) : (float2(h1(fi * 3.1 + 1.0), h1(fi * 5.7 + 2.0)) - 0.5) * 2.0 * amzp_spread * asp);
            float st = i == 0 ? 0.0 : h1(fi * 9.3 + 4.0) * amzp_stagger;
            float pi = clamp((C - st) / max(1.0 - st, 0.05), 0.0, 1.0);
            float far = length(abs(c) + asp * 0.5) * 1.15 + 0.1;
            float r = far * pow(pi, 1.05) * (0.85 + 0.3 * h1(fi * 1.7 + 8.0));
            r = pi >= 1.0 ? far * 1.2 : r;
            float2 d = q - c;
            float dl = length(d);
            float2 un = dl > 1e-5 ? d / dl : float2(1.0, 0.0);
            float ang = fbm(un * amzp_detail * 0.5 + fi * 7.3) - 0.5;
            float ten = pow(vnoise(un * (5.0 + amzp_detail) + fi * 3.9 + 11.0), 7.0) * amzp_tendrils * 1.6;
            float fine = (fbm(q * amzp_detail * 6.0 + fi) - 0.5) * 0.12;
            float edge = r * (1.0 + ang * amzp_rough * 0.7 + ten) + fine * amzp_rough * min(r, 0.25);
            f = max(f, edge - dl);
            if (dropOn && pi > 0.02 && pi < 0.999) {
                float dd = length(dc - c);
                float zone = r * (1.0 + 0.45 * amzp_drops) + 0.02;
                if (dd > r * 0.9 && dd < zone) dropM = max(dropM, smoothstep(dr + fe, dr - fe, length(q - dc)));
            }
        }
        float m0 = smoothstep(-fe, fe, f);
        dropM *= 1.0 - m0;
        float m = max(m0, dropM);
        float rim = rw > 0.0 ? (1.0 - smoothstep(rw - fe, rw + fe, f)) * m0 : 0.0;
        rim = max(rim, dropM * 0.6 * step(0.0001, rw));
        float vis = int(amzp_dir) == 1 ? 1.0 - m : m;
        float rimV = int(amzp_dir) == 1 ? (rw > 0.0 ? (1.0 - smoothstep(rw - fe, rw + fe, -f)) * (1.0 - m) : 0.0) : rim;
        float4 o = src * vis;
        o.rgb = mix(o.rgb, amzp_rimColor.rgb * o.a, clamp(rimV * amzp_rimOp, 0.0, 1.0));
        amzOutput = o;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
